documents.spec:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
base: SRC
input:
  SRC: {path: src.csv, types: {ID: int}}
  LAB: {path: lab.csv, types: {ID: int, SEQ: int, VAL: float}}
output: {path: out.csv, columns: [ID, SEQ]}
intermediates:
  - id: ONE
    dataset: LAB
    key: {KEYN: ID}
    derivations:
      KEYN:
        case:
          - {when: "LAB.VAL IS NULL", then: LAB.ID}
          - {otherwise: LAB.VAL}
    verifications:
      - unique: [KEYN]
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: ONE.SEQ}

edits.to:
  - unique: {columns: [KEYN], severity: warning}
order_by: [LAB.SEQ]
keep: last
